import type { FantasyCheckContext, FantasyEvent, FantasyEventChoice, FantasyJob, FantasyRace, FantasySkill, FantasyStat, FantasyStats } from './fantasy.ts';

type L = Record<'ko' | 'en' | 'ja', string>;
type Text = [ko: string, en: string, ja: string];
const l = ([ko, en, ja]: Text): L => ({ ko, en, ja });
type Skill = FantasySkill & { names: L; descriptions: L };
type Choice = FantasyEventChoice & { labels: L; successes: L; failures: L };
type Race = FantasyRace & { descriptions: L };
type Job = FantasyJob & { descriptions: L };
const skill = (id: string, title: Text, body: Text, effect: FantasySkill['effect'], power: number, mp = 0, stat?: FantasyStat): Skill => ({ id: id.replace(/^approved-/, 'approved-skill-'), names: l(title), name: title[2], descriptions: l(body), description: body[2], kind: mp ? 'active' : 'passive', mp, effect, power, ...(stat ? { stat } : {}) });
type Approach = { labels: L; stat: FantasyStat; context: FantasyCheckContext; dc: number };
const a = (label: Text, stat: FantasyStat, context: FantasyCheckContext, dc = 12): Approach => ({ labels: l(label), stat, context, dc });
function scene(id: string, title: Text, body: Text, approaches: [Approach, Approach], success: Text, failure: Text, item: string, job?: string, race?: string): FantasyEvent {
  const choices: Choice[] = approaches.map((approach, index) => ({ ...approach, id: index ? 'alternative' : 'approach', label: approach.labels.ja, success: success[2], failure: failure[2], successes: l(success), failures: l(failure), gold: index ? 30 : 24, item }));
  return { id, names: l(title), name: title[2], descriptions: l(body), description: body[2], choices, ...(job ? { job } : {}), ...(race ? { races: [race] } : {}) };
}
const event = (job: string, slug: string, title: Text, body: Text, approaches: [Approach, Approach], success: Text, failure: Text, item: string) => scene(`approved-${job}-${slug}`, title, body, approaches, success, failure, item, job);
const racial = (race: string, title: Text, body: Text, approaches: [Approach, Approach], success: Text, failure: Text, item: string) => scene(`approved-racial-${race}`, title, body, approaches, success, failure, item, undefined, race);
const race = (id: string, family: string, title: Text, body: Text, weight: number, modifiers: Partial<FantasyStats>, affinity: string[], skills: [Skill, Skill]): Race => ({ id, family, names: l(title), name: title[2], descriptions: l(body), description: body[2], rarity: '希少', weight, modifiers, affinity, skills });

